use super::*;
fn binding() -> MutationAdmissionBinding { MutationAdmissionBinding { runtime_identity_digest: [1;32], principal_digest: [2;32], gate_epoch: 3 } }
#[test] fn intent_expiry_above_thirty_seconds_is_rejected() { assert!(DestructiveIntentManager::new(Duration::from_secs(31)).is_err()); }
#[test] fn intent_manager_rejects_zero_lifetime() { assert!(DestructiveIntentManager::new(Duration::ZERO).is_err()); }
#[tokio::test] async fn wrong_window_generation_expiry_and_replay_fail_closed() {
 let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let now=Instant::now(); let (reference, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap();
 assert!(manager.consume(&reference,"other",7,now).is_err()); drop(decision);
 let (reference, _decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); assert!(manager.consume(&reference,"main",8,now).is_err());
 let (reference, _decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); assert!(manager.consume(&reference,"main",7,now+Duration::from_secs(30)).is_err());
 let (reference, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); let completion=manager.consume(&reference,"main",7,now).unwrap(); assert!(decision.await.unwrap()); assert!(manager.consume(&reference,"main",7,now).is_err()); assert!(!manager.try_commit(&reference,binding(),[5;32],now)); assert!(manager.try_commit(&reference,binding(),[4;32],now)); manager.finish(&reference,Ok(())); assert!(completion.await.unwrap().is_ok());
}
#[tokio::test] async fn invalidate_window_cancels_pending_and_consumed_before_commit() { let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let (reference, decision)=manager.issue("main",7,binding(),[4;32],Instant::now()).unwrap(); manager.invalidate_window("main"); assert!(!decision.await.unwrap()); assert!(manager.consume(&reference,"main",7,Instant::now()).is_err()); let (reference, decision)=manager.issue("main",7,binding(),[4;32],Instant::now()).unwrap(); let completion=manager.consume(&reference,"main",7,Instant::now()).unwrap(); assert!(decision.await.unwrap()); manager.invalidate_window("main"); assert!(!manager.try_commit(&reference,binding(),[4;32],Instant::now())); assert!(completion.await.unwrap().is_err()); }
#[tokio::test] async fn committed_lease_survives_lifecycle_fence_until_task_completion() { let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let now=Instant::now(); let (reference, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); let completion=manager.consume(&reference,"main",7,now).unwrap(); assert!(decision.await.unwrap()); assert!(manager.try_commit(&reference,binding(),[4;32],now)); manager.invalidate_window("main"); manager.finish(&reference,Err(())); assert!(completion.await.unwrap().is_err()); assert!(manager.consume(&reference,"main",7,now).is_err()); }
#[tokio::test] async fn consumed_intent_cannot_commit_at_or_after_expiry() { let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let now=Instant::now(); let (reference, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); let completion=manager.consume(&reference,"main",7,now).unwrap(); assert!(decision.await.unwrap()); let expiry=now+Duration::from_secs(30); assert!(!manager.try_commit(&reference,binding(),[4;32],expiry)); assert!(!manager.try_commit(&reference,binding(),[4;32],expiry+Duration::from_nanos(1))); manager.finish(&reference,Err(())); assert!(completion.await.unwrap().is_err()); }
#[tokio::test] async fn committed_intent_retains_completion_after_ttl() { let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let now=Instant::now(); let (reference, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); let completion=manager.consume(&reference,"main",7,now).unwrap(); assert!(decision.await.unwrap()); assert!(manager.try_commit(&reference,binding(),[4;32],now)); assert!(manager.issue("main",7,binding(),[5;32],now+Duration::from_secs(30)).is_ok()); manager.finish(&reference,Ok(())); assert!(completion.await.unwrap().is_ok()); }
#[tokio::test] async fn cancellation_cleanup_recovers_capacity_after_more_than_sixty_four_leases() { let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let now=Instant::now(); let mut decisions=Vec::new(); for _ in 0..64 { let (_, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); decisions.push(decision); } assert!(manager.issue("main",7,binding(),[4;32],now).is_err()); manager.invalidate_window("main"); for decision in decisions { assert!(!decision.await.unwrap()); } assert!(manager.issue("main",7,binding(),[4;32],now).is_ok()); }
#[test] fn dropped_confirmation_receiver_removes_the_unconsumed_lease() { let manager=DestructiveIntentManager::new(Duration::from_secs(30)).unwrap(); let now=Instant::now(); let (reference, decision)=manager.issue("main",7,binding(),[4;32],now).unwrap(); drop(decision); assert!(manager.consume(&reference,"main",7,now).is_err()); for _ in 0..64 { assert!(manager.issue("main",7,binding(),[4;32],now).is_ok()); } }
